reference_solution:
#include <stdio.h>

int count_char(const char *s, char c) {
    int count = 0;
    for (const char *p = s; *p != '\0'; p++) {
        if (*p == c) count++;
    }
    return count;
}

int main(void) {
    char s[100];
    char c;
    if (scanf("%99s %c", s, &c) != 2) return 1;
    printf("%d\n", count_char(s, c));
    return 0;
}
